    h, w = len(grid), len(grid[0])

    def separator_lines(length, values):
        lines = []
        for i in range(length):
            counts = {}
            for v in values(i):
                counts[v] = counts.get(v, 0) + 1
            if max(counts.values()) >= length - 2:
                lines.append(i)
        return lines

    rows = separator_lines(h, lambda r: grid[r])
    cols = separator_lines(w, lambda c: [grid[r][c] for r in range(h)])

    # Use the dominant color of the non-line interior as the blank output.
    line_rows = set(rows)
    line_cols = set(cols)
    counts = {}
    for r in range(h):
        if r in line_rows:
            continue
        for c in range(w):
            if c not in line_cols:
                v = grid[r][c]
                counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)

